{
  "summary": "Move the metrics field from the world snapshot payload to the runtime object in the session state message. This requires updating the session state builder to include metrics in the runtime payload and adjusting the client reducer to read metrics from sessionState.runtime.metrics instead of worldSnapshot.payload.metrics.",
  "files": [
    {
      "path": "apps/game-runtime/src/runtime/sessionState.ts",
      "content": "import type { SessionStateMessage, WorldSnapshotMessage } from "@codexgame/protocol";
import type { RuntimeMetrics } from "./metrics";

export function buildMessages(metrics: RuntimeMetrics): {
  sessionState: SessionStateMessage;
  worldSnapshot: WorldSnapshotMessage;
} {
  return {
    sessionState: {
      type: "session.state",
      payload: {
        phase: "running",
        runtime: {
          model: "local-qwen",
          tickMs: 200,
          metrics,
        },
      },
    },
    worldSnapshot: {
      type: "world.snapshot",
      payload: {
        tick: 42,
        world: {},
      },
    } as unknown as WorldSnapshotMessage,
  };
}

